const details = await browserjs(tabId, () => {
  const chooseBtns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent?.includes('Choose your room'));
  return chooseBtns.map((btn, idx) => {
    // Traverse up to find the full card container
    let p = btn;
    for (let i = 0; i < 10; i++) {
      if (!p.parentElement) break;
      p = p.parentElement;
